-- Etapa 5. Leitura; escopos geral e delivered se sobrepõem.
SELECT count(*) pedidos,count(*) FILTER(WHERE cliente_sk IN(-1,-2)) identidade_tecnica,count(*) FILTER(WHERE localizacao_sk IN(-1,-2)) localizacao_tecnica,count(*) FILTER(WHERE order_purchase_timestamp IS NULL) compra_ausente,count(*) FILTER(WHERE order_status='delivered' AND order_purchase_timestamp IS NULL) delivered_compra_ausente,count(DISTINCT cliente_sk) FILTER(WHERE cliente_sk>0) identidades_regulares,(SELECT count(*) FROM gold.dim_clientes WHERE membro_tipo='regular') identidades_dimensao FROM gold.fato_pedidos;
